// Generated by vibelang from src/features/navigation/router.ts; the migrate flow writes it again with each batch.
/** The router owns route matching; a command never moves to its not-found page. */
export const navigateTo = (router, origin) => async (path) => {
    const url = new URL(path, origin);
    if (router.matchRoutes(url.pathname).some(match => match._notFound))
        throw new Error("Page not found");
    await router.navigate({ href: path });
};
